=CREATE TABLE IF NOT EXISTS public.ops_migration_mutex (
  lock_name text PRIMARY KEY,
  owner text,
  locked_until timestamptz NOT NULL DEFAULT '-infinity'
);
-- The lock is held for a bounded window. A run that dies without releasing it
-- frees the mutex when the window expires, instead of blocking OPS-04 forever.
-- 'infinity' is the legacy sentinel written before this TTL existed; it is
-- reclaimable because no current execution writes it any more.
INSERT INTO public.ops_migration_mutex (lock_name, owner, locked_until)
VALUES ('OPS-04:renovation_dev', '{{ $execution.id }}', now() + interval '30 minutes')
ON CONFLICT (lock_name) DO UPDATE
SET owner = EXCLUDED.owner, locked_until = EXCLUDED.locked_until
WHERE public.ops_migration_mutex.owner IS NULL
   OR public.ops_migration_mutex.owner = EXCLUDED.owner
   OR public.ops_migration_mutex.locked_until < now()
   OR public.ops_migration_mutex.locked_until = 'infinity';
DO $lock$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.ops_migration_mutex
    WHERE lock_name = 'OPS-04:renovation_dev' AND owner = '{{ $execution.id }}'
  ) THEN
    RAISE EXCEPTION 'OPS-04 renovation_dev migration lock is held by another execution';
  END IF;
END;
$lock$;
SELECT 'acquired' AS lock_status;

=UPDATE public.ops_migration_mutex
SET owner = NULL, locked_until = now()
WHERE lock_name = 'OPS-04:renovation_dev' AND owner = '{{ $execution.id }}';
SELECT 'completed' AS status, 'Todas las migraciones pendientes aplicadas exitosamente' AS message;

=UPDATE public.ops_migration_mutex
SET owner = NULL, locked_until = now()
WHERE lock_name = 'OPS-04:renovation_dev' AND owner = '{{ $execution.id }}';
SELECT 'ok' AS status, 'No hay migraciones pendientes. Base de datos al dia.' AS message;
